# Generated by manage.py generate_test_cases.
from django.urls import reverse
from playwright.sync_api import expect
from bloomerp.tests.components.communication.instant_messaging.phone_fixtures import (
    PhoneDirectoryFixtures,
)
from bloomerp.models.communication.voip import VoIPNumber
from bloomerp.models.communication.instant_messaging import IMConversation, IMConnection
from bloomerp.tests.base import (
    BloomerpE2ETestCase,
    E2EAction,
    E2ERequestScenario,
)


class TestVoIpconnectionsViewE2E(PhoneDirectoryFixtures, BloomerpE2ETestCase):
    """Tests class `VoIPConnectionsView` from `bloomerp/views/communication/voip/connections.py`."""

    view_name = "voip_connections"

    def get_test_scenarios(self) -> list[E2ERequestScenario]:
        """Exercise the actual provider picker, dependent line selection and chat rendering."""
        return [
            E2ERequestScenario(
                name="Phone directory opens line selection and shared chat",
                user=self.normal_user,
                url=reverse("voip_connections"),
                prepare=self.prepare_directory,
                actions=[
                    E2EAction(
                        name="Choose phone recipient and business line",
                        execute=self.choose_recipient,
                        validators=self.verify_phone_chat,
                    )
                ],
            )
        ]

    def prepare_directory(self) -> None:
        """Configure two authorized lines so the UI must show the second selection step."""
        self.phone_setup()
        number = VoIPNumber.objects.create(
            connection=self.connection,
            number="+32470000009",
            provider_number_id="PN" + "9" * 32,
            name="Second line",
            supports_sms=True,
            supports_voice=True,
        )
        number.assigned_users.add(self.normal_user)

    def choose_recipient(self) -> None:
        """Navigate the real messaging shell and complete its provider-defined selection flow."""
        shell = self.page.locator('[bloomerp-component="bloomerp:messaging-panel"]')
        shell.locator("[data-floating-panel-launcher]").click()
        shell.locator('button[aria-haspopup="true"]').first.click()
        shell.locator('input[name="recipient_query"]').fill("Phone directory contact")
        shell.locator(".im-recipient").filter(
            has_text="Phone directory contact"
        ).click()
        expect(shell.locator("[data-chat-view]")).to_be_visible()
        shell.locator("#im-conversation-host button").filter(
            has_text="Second line"
        ).click()

    def verify_phone_chat(self) -> None:
        """Verify the selected line, authorized label and call controls without placing a paid call."""
        host = self.page.locator("#im-conversation-host")
        expect(host.locator(".im-chat-header")).to_contain_text(
            "Phone directory contact"
        )
        expect(host.locator('[data-phone-action="call"]')).to_be_visible()
        expect(host.locator(".im-chat-header")).to_contain_text("+32470000009")
        self.assertTrue(
            IMConversation.objects.filter(
                provider_key="phone",
                phone_address=self.contact.phone,
                voip_number__number="+32470000009",
            ).exists()
        )
        self.assertFalse(IMConnection.objects.exists())
